// Security-review fixes for R4.7: the independent corpus pair, per-rule timing on 1 MB adversarial
// input, and one test per review finding. Corpus cases are generated by gen-independent.mjs.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { compileRedactionConfig } from "../../src/redaction/config.ts";
import { createRedactor, redactorFromConfig } from "../../src/redaction/redactor.ts";

const here = dirname(fileURLToPath(import.meta.url));
const gen = join(here, ".generated");
const read = (f: string): string => readFileSync(join(gen, f), "utf8");
const red = createRedactor();
const leaks = (out: string, s: string): boolean =>
  out.includes(s) || out.includes(JSON.stringify(s).slice(1, -1));
const wrap = (content: string): string =>
  JSON.stringify({ type: "user", message: { content: [{ type: "tool_result", content }] } });

const secretLines = read("independent-secret-corpus.jsonl").split("\n").filter(Boolean);
const expected = JSON.parse(read("independent-secret-corpus.expected.json")) as {
  label: string;
  secrets: string[];
}[];
const benign = readFileSync(join(here, "independent-benign-corpus.txt"), "utf8")
  .split("\n")
  .filter(Boolean)
  .map((l) => JSON.parse(l) as string);

describe("independent corpora (security reviewer)", () => {
  it("secret corpus: 0 leaks", () => {
    expect(secretLines).toHaveLength(expected.length);
    const bad: string[] = [];
    let n = 0;
    secretLines.forEach((line, i) => {
      const out = red.redactLine(line);
      for (const s of expected[i]!.secrets) {
        n += 1;
        if (leaks(out, s)) bad.push(expected[i]!.label);
      }
      let parsed = true;
      try {
        JSON.parse(line);
      } catch {
        parsed = false;
      }
      if (parsed) expect(() => JSON.parse(out), expected[i]!.label).not.toThrow();
    });
    console.log(
      `independent secret corpus: leaks: ${bad.length}/${n} secrets, ${secretLines.length} lines`,
    );
    expect(bad).toEqual([]);
  });

  it("benign corpus: under 2% of lines change, and the named shapes stay as they are", () => {
    const changed = benign.filter((t) => red.redactLine(wrap(t)) !== wrap(t));
    const pct = (changed.length / benign.length) * 100;
    console.log(
      `independent benign corpus: false positives: ${changed.length}/${benign.length} = ${pct.toFixed(1)}%`,
    );
    if (changed.length > 0) console.log(changed.map((l) => `  FP: ${l}`).join("\n"));
    expect(pct).toBeLessThan(2);
    for (const t of [
      "PWD=/c/Users/user/repo",
      "pwd: /home/user/project",
      "credentials: 'include'",
      "SECRET_KEY = env('DJANGO_SECRET_KEY')",
      "Authorization: Bearer ${token}",
    ]) {
      expect(red.redactLine(wrap(t)), t).toBe(wrap(t));
    }
  });
});

// --- one test per review finding ---

describe("security review fixes", () => {
  const sec = (text: string, secret: string): void => {
    const out = red.redactLine(wrap(text));
    expect(out, text).not.toContain(secret);
    expect(out, text).toContain("[redacted:");
  };

  it("HIGH 2: strong keys redact bare values with special characters", () => {
    sec("Password=P@ssw0rd!2024;", "P@ssw0rd!2024");
    sec("Pwd=Xk9!mQ2#zL;", "Xk9!mQ2#zL");
    sec("  password: P@ssw0rd!2024", "P@ssw0rd!2024");
    sec("export db_password=P@ss!w0rd#", "P@ss!w0rd#");
    const hvs = "hvs." + "CAESIJx7vR2mN9pL4kT8wZ1yB5cD";
    sec("vault login --token=" + hvs, hvs);
  });

  it("HIGH 3: auth, _auth, AccountKey and passphrase are credential keys", () => {
    sec(
      '{"auths":{"https://index.docker.io/v1/":{"auth":"dXNlcjpQ' + 'YXNzdzByZDEyMw=="}}}',
      "dXNlcjpQYXNzdzByZDEyMw==",
    );
    sec("//npm.corp.example/:_" + "auth=dXNlcjpQ" + "YXNzdzByZDEyMw==", "dXNlcjpQYXNzdzByZDEyMw==");
    sec("AccountName=acct;Account" + "Key=Eby8vdM0/K1SZFPTOtr/KBHBeksoGMGw==;", "Eby8vdM0/K1SZFPTOtr");
    sec("GPG_PASSPHRASE=Lw8Kq2Ns7Rtz", "Lw8Kq2Ns7Rtz");
    sec("passphrase: correct-horse-battery-9", "correct-horse-battery-9");
    const o = JSON.parse(
      red.redactLine('{"auth":"dXNlcjpQ' + 'YXNzdzByZDEyMw==","passphrase":"correct horse"}'),
    );
    expect(o.auth).toBe("[redacted:secret-key]");
    expect(o.passphrase).toBe("[redacted:secret-key]");
  });

  it("MEDIUM 4: space-separated CLI flags, setx and cookies", () => {
    sec("mysql -u root -pXk9mQ2zLp4", "Xk9mQ2zLp4");
    sec("mysqladmin --password Xk9mQ2zLp4", "Xk9mQ2zLp4");
    sec("docker login -u bob -p Xk9mQ2zLp4 reg", "Xk9mQ2zLp4");
    sec("cli deploy --token 9f8e7d6c5b4a39281706", "9f8e7d6c5b4a39281706");
    sec("az login --service-principal -u app -p Qx8~Zp3.Lm7_Rt2", "Qx8~Zp3.Lm7_Rt2");
    sec("setx GITHUB_TOKEN abcdef0123456789abcdef0123456789abcdef01", "abcdef0123456789abcdef01");
    sec(
      "Set-Cookie: session=s%3AJx7vR2mN9pL4kT8wZ1yB5cD3fG6h; Path=/",
      "Jx7vR2mN9pL4kT8wZ1yB5cD3fG6h",
    );
    sec("Cookie: sessionid=9f8e7d6c5b4a39281706; csrftoken=abc", "9f8e7d6c5b4a39281706");
    for (const ok of [
      "docker run -p 8080:80 nginx",
      "mysql -p dbname",
      "setx PATH C:\\bin",
      "--password-stdin",
    ]) {
      expect(red.redactLine(wrap(ok)), ok).toBe(wrap(ok));
    }
  });

  it("MEDIUM 5: the structural key walk runs even when env-assignment is disabled", () => {
    const r = redactorFromConfig({ disableRules: ["env-assignment"] }).redactor;
    const line = JSON.stringify({
      toolUseResult: { config: { password: "Lw8Kq2Ns7Rt", api_key: "4f9a8b7c6d5e" } },
    });
    const out = r.redactLine(line);
    expect(out).not.toContain("Lw8Kq2Ns7Rt");
    expect(out).not.toContain("4f9a8b7c6d5e");
  });

  it("MEDIUM 5 / LOW 9: a unicode-escaped raw line is not skipped by the gate", () => {
    const line = '{"type":"x","toolUseResult":{"\\u0070assword":"Lw8Kq2Ns7Rtz"}}';
    expect(red.redactLine(line)).not.toContain("Lw8Kq2Ns7Rtz");
    const dsn = JSON.stringify({
      sentryDsn: "https://abc123@o1.ingest.sentry.io/42",
      dsn: "https://k@o2.example.io/1",
    });
    expect(red.redactLine(dsn)).not.toContain("abc123");
  });

  it("MEDIUM 5: user deny patterns match across a window boundary", () => {
    const r = redactorFromConfig({
      deny: [{ name: "corp-id", pattern: "CORP-[0-9]{8}" }],
    }).redactor;
    for (const pad of [4090, 4096 - 3, 4096, 8192 - 5, 100]) {
      const out = r.redactLine(wrap("x".repeat(pad) + "CORP-12345678 tail"));
      expect(out, `pad ${pad}`).not.toContain("CORP-12345678");
      expect(out).toContain("[redacted:corp-id]");
    }
  });

  it("MEDIUM 5: deny patterns with quantified alternation or many unbounded quantifiers are rejected", () => {
    for (const p of ["(a|aa)+$", "(a|a)*$", "(\\w+\\s?)*$", "\\w*\\w*\\w*\\w*\\w*x", "(a|b){2,}"]) {
      const c = compileRedactionConfig({ deny: [{ name: "u", pattern: p }] });
      expect(c.ok, p).toBe(false);
    }
    expect(
      compileRedactionConfig({ deny: [{ name: "u", pattern: "CORP-[0-9]{1,12}\\s?[a-z]{1,9}" }] })
        .ok,
    ).toBe(true);
  });

  it("MEDIUM 6: escaped-slash URL credentials, long quoted values, SendGrid and webhooks", () => {
    sec(JSON.stringify({ u: "postgres:\\/\\/app:Xk9mQ2zLp4@db\\/x" }), "Xk9mQ2zLp4");
    sec("postgres:\\/\\/app:Xk9mQ2zLp4@db", "Xk9mQ2zLp4");
    const long = "Ab3dEf6hIj".repeat(110);
    sec(`API_KEY="${long}"`, long.slice(0, 60));
    sec(
      "SG.Ab3dEf6hIj9kLm2nOp5qRs.Tu8vWx1y" + "Za4bCd7eFg0hIj3kLm6nOp9qRs2tUv5wXy8",
      "Ab3dEf6hIj9kLm2nOp5qRs",
    );
    sec(
      "https://hooks.slack.com/s" + "ervices/T00000000/" + "B00000000/XXXXXXXXXXXXXXXXXXXXXXXX9",
      "XXXXXXXXXXXXXXXXXXXXXXXX9",
    );
    sec(
      "https://discord.com/api/" + "webhooks/1234567890/" + "Ab3dEf6hIj9kLm2nOp5qRs8tUv1wXy4zAb7c",
      "Ab3dEf6hIj9kLm2nOp5qRs8tUv1wXy4zAb7c",
    );
  });

  it("LOW 7: allow patterns are tested against the secret span, not the key prefix", () => {
    const r = redactorFromConfig({ allow: ["^DB_"] }).redactor;
    expect(r.redactLine(wrap("DB_PASSWORD=Lw8Kq2Ns7Rt"))).not.toContain("Lw8Kq2Ns7Rt");
    const r2 = redactorFromConfig({ allow: ["^EXAMPLE"] }).redactor;
    expect(r2.redactLine(wrap("DB_PASSWORD=EXAMPLE1234"))).toContain("EXAMPLE1234");
  });

  it("LOW 8: an invalid deny pattern does not echo the pattern", () => {
    const e =
      redactorFromConfig({ deny: [{ name: "pw", pattern: "MyRealPassw0rd!(" }] }).error ?? "";
    expect(e).toMatch(/deny\[0\] \(pw\)/);
    expect(e).not.toContain("MyRealPassw0rd");
    const a = redactorFromConfig({ allow: ["SecretValue123("] }).error ?? "";
    expect(a).not.toContain("SecretValue123");
  });

  it("code review 2: an unparseable line keeps its own escapes when the plain pass finds nothing new", () => {
    const line =
      '{"cmd": "echo \\"hi\\"\\n", "x": "export GH_TOKEN=ghp_FAKEabcdefg' +
      'hijklmnopqrstuv", broken';
    const out = red.redactLine(line);
    expect(out).not.toContain("ghp_FAKE");
    expect(out).toContain('echo \\"hi\\"\\n');
  });

  it("code review 4: a __proto__ key survives re-serialization", () => {
    const out = red.redactLine('{"__proto__":{"x":"1"},"password":"hunter2hunter2"}');
    expect(out).toContain('"__proto__":{"x":"1"}');
    expect(out).toContain("[redacted:secret-key]");
  });
});
